/* Engine dispatcher installed into the iter vtable + instr_types name-compare hook. */
#include "op1_synth.h"

/* generated by make_firmware.py: */
extern const op1_engine_t *const op1_engines[];      /* by order; [0] and unused orders 0 (original iter) */
extern const int              op1_engine_count;      /* highest order + 1 */
extern const char *const      op1_engine_names[];    /* by order - 1 ("" for unused orders), 0-terminated */
extern const char *const      op1_sample_engine_names[]; /* engines that use the sampler buffer */
extern const op1_fx_t *const  op1_fxs[];              /* by order; [0] and unused orders 0 (original filter) */
extern const int              op1_fx_count;          /* highest order + 1 */
extern const char *const      op1_fx_names[];
extern const op1_screen_t *const op1_engine_screens[];  /* per engine (0 = none) */
extern const char *const      op1_engine_svgs[];
extern const op1_screen_t *const op1_fx_screens[];      /* per FX (0 = generic fxgeneric.svg) */
extern const char *const      op1_fx_svgs[];

/* original TE iter voice methods (fw 246) */
#define ITER_RENDER   ((void (*)(void *, int16_t *, const int16_t *))0x019B99D4)
#define ITER_NOTE_ON  ((void (*)(void *, const int16_t *))0x019B9B8A)
#define ITER_NOTE_OFF ((void (*)(void *))0x019B996C)

static uint8_t voice_engine[OP1_VOICES];

/* selector word -> engine / FX order, 0 if this build has no plugin with that order (stock iter / filter) */
static int engine_index(int n) { return (n > 0 && n < op1_engine_count && op1_engines[n]) ? n : 0; }
static int fx_index(int n)     { return (n > 0 && n < op1_fx_count && op1_fxs[n]) ? n : 0; }

static int engine_of(const int16_t *params)
{
    return engine_index(params[4] - OP1_ENGINE_MAGIC);
}

void synth_note_on(void *self, const int16_t *params)
{
    int e = engine_of(params);
    voice_engine[op1_voice_index(self)] = (uint8_t)e;
    if (e) op1_engines[e]->note_on(self, params); else ITER_NOTE_ON(self, params);
}

/* per-voice output peak of stock iter voices (screens/iterlab.c), Q15, written once per block */
volatile int16_t op1_iter_level[6];

void synth_render(void *self, int16_t *out, const int16_t *params)
{
    int v = op1_voice_index(self), e = engine_of(params);
    if (e != voice_engine[v]) {                       /* engine switched while voice alive */
        voice_engine[v] = (uint8_t)e;
        if (e) op1_engines[e]->note_on(self, params); else ITER_NOTE_ON(self, params);
    }
    if (e) { op1_engines[e]->render(self, out, params); op1_iter_level[v] = 0; return; }
    ITER_RENDER(self, out, params);
    int32_t pk = 0;
    for (int i = 0; i < OP1_BLOCK; i += 4) { int32_t a = out[i] < 0 ? -out[i] : out[i]; if (a > pk) pk = a; }
    op1_iter_level[v] = (int16_t)(pk > 32767 ? 32767 : pk);
}

void synth_note_off(void *self)
{
    int e = voice_engine[op1_voice_index(self)];
    if (!e) ITER_NOTE_OFF(self);
    else if (op1_engines[e]->note_off) op1_engines[e]->note_off(self);
}

int synth_query(void *self) { (void)self; return 0; }

/* ---- replacement for TE::shared::instr_types name compare @0x019B975C ----
 * bool eq(const char *table_name, const std::string *s)   (Dinkumware string:
 *   +0x04 inline buf / heap ptr, +0x14 size, +0x18 capacity; heap if capacity > 15)
 * Adds: table entry "iter" also matches every custom engine name.                         */
typedef struct { uint32_t alloc; union { char buf[16]; char *ptr; } u; uint32_t size, cap; } dstring;

static int streq_n(const char *a, const char *b, uint32_t n)
{
    uint32_t i = 0;
    for (; i < n; i++) if (a[i] != b[i] || !b[i]) return 0;
    return b[n] == 0;
}

/* A patch whose synth type is unknown (a custom engine removed from the build, e.g. "paul") failed parse_patch_json
 * with error 1 -> assert patch.cpp:390 "Invalid synth patch <type>: - error 1", the OP-1 locked. Unknown names now
 * also match "iter": the slot loads as the stock iter synth (its knobs[4] selector names no engine -> lab screen). */
static const char *const stock_synth_names[] = { "fm", "digital", "drwave", "string", "cluster", "pulse", "sampler",
                                                 "phase", "drum", "dbox", "ls", "dna", "dsynth", "voltage", 0 };
int instr_name_eq(const char *name, const dstring *s)
{
    const char *p = s->cap > 15 ? s->u.ptr : s->u.buf;
    if (streq_n(p, name, s->size)) return 1;
    if (name[0] == 'i' && name[1] == 't' && name[2] == 'e' && name[3] == 'r' && !name[4]) {
        if (!s->size) return 0;
        for (const char *const *n = stock_synth_names; *n; n++)
            if (streq_n(p, *n, s->size)) return 0;      /* a stock type: its own entry matches */
        return 1;                                       /* custom engine or unknown name -> iter */
    }
    return 0;
}

/* ---- replacement for the "type == sampler" check in patch::sample_path (CALL @0x01A01844) ----
 * bool eq(const std::string *s, const char *lit): also true for engines flagged uses_sample, so
 * their slot's synth_<slot>.raw is loaded into the sampler buffer at boot.                   */
int sample_type_eq(const dstring *s, const char *lit)
{
    const char *p = s->cap > 15 ? s->u.ptr : s->u.buf;
    if (streq_n(p, lit, s->size)) return 1;
    for (const char *const *n = op1_sample_engine_names; *n; n++)
        if (streq_n(p, *n, s->size)) return 1;
    return 0;
}

/* ---- input key: "keyboard to sample" also for sample engines (granular) ----
 * global_controller::on_key (code 0x2B, @0x019AC8B4) and on_key_shift (@0x019ACC7C) open the sampler record mode
 * only if the synth slot type is 6 (sampler). hook.S replaces those compares with rec_type_ok(type): also true
 * for type 14 (iter) running an engine flagged uses_sample. The recording goes to the slot's sample buffer. */
extern const char *const op1_engine_names[];
extern const int op1_engine_count;
int rec_type_ok(int type)
{
    if (type == 6) return 1;
    if (type != 14) return 0;
    int n = engine_index(op1_synth_knobs(*(volatile int *)0xFF8016D4)[4] - OP1_ENGINE_MAGIC);
    if (!n) return 0;
    for (const char *const *s = op1_sample_engine_names; *s; s++) {
        const char *a = op1_engine_names[n - 1], *b = *s;
        while (*a && *a == *b) { a++; b++; }
        if (*a == *b) return 1;
    }
    return 0;
}

/* end of "keyboard to sample" (mic_line record key-up 0x019DEE1C): CALL @0x019DEEF2 to 0x01A02A46(slot, base_freq,
 * length) turns the slot's patch into a fresh sampler patch. For a sample engine (granular) skip it: the slot stays
 * on its engine and knobs; the buffer is still marked for saving (0x019412AC follows). */
void rec_end_patch(int slot, uint32_t base_freq, int len)
{
    if (rec_type_ok(*(volatile int *)(0xFF8016E4 + slot * 4)) && *(volatile int *)(0xFF8016E4 + slot * 4) == 14) return;
    ((void (*)(int, uint32_t, int))0x01A02A46)(slot, base_freq, len);
}

/* ================= effects: dispatcher in the "filter" FX vtable (0x01910C94) ================= */
#define FILTER_RENDER ((void (*)(void *, int16_t *, const int16_t *))0x019E7934)
#define FILTER_INIT   ((void (*)(void *, int))0x019E780A)

static int fx_pos = 0, fx_cur = -1, fx_cur_master = -1;

void fx_init(void *self, int pos)
{
    fx_pos = pos & 1;                              /* one mono FX object: synth (0) or drum (1) */
    fx_cur = -1;                                   /* (re)initialise custom FX on first render */
    FILTER_INIT(self, pos);
}

/* ---- master FX: stereo filter wrapper (vtable 0x01910CB4): two mono filters at +4 / +0x28 (pos 2 / 3),
 * render(self, L[64], R[64], params) 0x019E7EE4 calls the filter render directly (not via the mono vtable).
 * Custom FX run once at FX position 2 (scratch 0x01B0EE48, the master delay's) on the mono sum m = (L+R)/2;
 * the FX's change y - m is added to both channels, so the dry stereo image stays and the wet part is centred. */
#define FILTER_ST_RENDER ((void (*)(void *, int16_t *, int16_t *, const int16_t *))0x019E7EE4)
#define FILTER_ST_INIT   ((void (*)(void *))0x019E78D0)
void fx_init_stereo(void *self)
{
    fx_cur_master = -1;
    FILTER_ST_INIT(self);
}

static void fx_sanitize(void);
void fx_render_stereo(void *self, int16_t *l, int16_t *r, const int16_t *params)
{
    fx_sanitize();
    int n = params[4] - OP1_ENGINE_MAGIC;
    int e = fx_index(n);
    if (!e) { fx_cur_master = 0; FILTER_ST_RENDER(self, l, r, params); return; }
    if (e != fx_cur_master) { fx_cur_master = e; op1_fxs[e]->init(OP1_FX_MASTER); }
    int16_t m[OP1_FX_BLOCK], y[OP1_FX_BLOCK];
    for (int i = 0; i < OP1_FX_BLOCK; i++) y[i] = m[i] = (int16_t)((l[i] + r[i]) >> 1);
    op1_fxs[e]->render(OP1_FX_MASTER, y, params);
    for (int i = 0; i < OP1_FX_BLOCK; i++) {
        int32_t d = y[i] - m[i];
        l[i] = op1_sat16(l[i] + d);
        r[i] = op1_sat16(r[i] + d);
    }
}

/* Keep the raw knob words of every slot running a custom FX inside the filter type's ranges.
 * read_fx_param asserts ("Instr/Drum fx param out of range") on anything outside and the OP-1 locks up -
 * at every boot while such a value is stored (old builds wrote tape knob 3 = 6000 < min 8192).
 * Ranges from the runtime table (fx type 5) when filled, else the values computed from 0x01A1E914. */
static const int16_t fx_rng_default[4][2] = { { 64, 14528 }, { 0, 24576 }, { 0, 22528 }, { 8192, 32767 } };
static void fx_sanitize(void)
{
    for (int pos = 0; pos < 3; pos++)
        for (int slot = 0; slot < (pos == 2 ? 1 : 8); slot++) {
            int16_t *p = (int16_t *)(pos == 2 ? 0xFF8016C4 : (pos ? 0xFF8015C4 : 0xFF801444) + slot * 16);   /* 2: master */
            int n = p[4] - OP1_ENGINE_MAGIC;
            if (!fx_index(n)) continue;
            if (pos == 2 && *(volatile int *)0xFF801090 != 5) continue;   /* master runs another FX type */
            for (int i = 0; i < 4; i++) {
                const int16_t *rg = (const int16_t *)(0x01DE5C50 + 5 * 0x30 + i * 6);
                int lo = rg[0], hi = rg[1];
                if (hi <= lo) { lo = fx_rng_default[i][0]; hi = fx_rng_default[i][1]; }
                if (p[i] < lo) p[i] = (int16_t)lo; else if (p[i] > hi) p[i] = (int16_t)hi;
            }
        }
}

/* replaces every firmware CALL to read_fx_param (8 sites, see make_firmware.py HOOKS) */
void *read_fx_param_safe(int slot, int pos)
{
    fx_sanitize();
    return ((void *(*)(int, int))0x01A28DA0)(slot, pos);
}

void fx_render(void *self, int16_t *buf, const int16_t *params)
{
    fx_sanitize();
    int n = params[4] - OP1_ENGINE_MAGIC;
    int e = fx_index(n);
    if (!e) { fx_cur = 0; FILTER_RENDER(self, buf, params); return; }
    if (e != fx_cur) { fx_cur = e; op1_fxs[e]->init(fx_pos); }
    op1_fxs[e]->render(fx_pos, buf, params);
}

/* replacement for TE::shared::fx_types name compare @0x019AAD8E: entry "filter" also matches
 * every custom FX name -> they all resolve to fx type 5 (filter object, mmmf.svg screen). */
/* ---- euclid sequencer (seq/euclid.c): extra sequencer, runs as type 3 (finger) + eu_active[mode] ----
 * seq_types row "euclid"; SeqIds::from_name (3 CALLs: set_sequencer 0x01A42A2E, load 0x01A42BDC/0x01A42CE0)
 * -> eu_seq_from_name; SeqIds::name(type) 0x01A422EC -> eu_seq_name (JUMP at entry); the finger screen slot 0x2D
 * holds the euclid screen while euclid is active in the current mode (eu_sync_screen). */
extern volatile uint8_t eu_active[2];
#define SEQ_FROM_NAME ((int (*)(const dstring *))0x01A42344)
#define SEQ_TABLE     ((const struct { const char *name; int type; } *)0x018FA634)
#define CUR_MODE()    (*(volatile int *)0x01DE4C40 == 1)
/* dots (seq/dots.c) works the same way with its own flag dt_active[mode]; at most one flag is set per mode */
extern volatile uint8_t dt_active[2];
/* oracle (seq/oracle.c) and peal (seq/peal.c): same mechanism, flags ora_active[mode] / pl_active[mode] */
extern volatile uint8_t ora_active[2], pl_active[2];
int eu_seq_from_name(const dstring *s)
{
    const char *p = s->cap > 15 ? s->u.ptr : s->u.buf;
    int eu = streq_n(p, "euclid", s->size), d = streq_n(p, "dots", s->size), orc = streq_n(p, "oracle", s->size)
        || streq_n(p, "shield", s->size), pe = streq_n(p, "peal", s->size);   /* (shield: its pre-release name) */
    eu_active[CUR_MODE()] = (uint8_t)eu;
    dt_active[CUR_MODE()] = (uint8_t)d;
    ora_active[CUR_MODE()] = (uint8_t)orc;
    pl_active[CUR_MODE()] = (uint8_t)pe;
    return eu || d || orc || pe ? 3 : SEQ_FROM_NAME(s);
}
const char *eu_seq_name(int type)
{
    if (type == 3 && eu_active[CUR_MODE()]) return "euclid";
    if (type == 3 && dt_active[CUR_MODE()]) return "dots";
    if (type == 3 && ora_active[CUR_MODE()]) return "oracle";
    if (type == 3 && pl_active[CUR_MODE()]) return "peal";
    for (int i = 0; i < 6; i++) if (SEQ_TABLE[i].type == type) return SEQ_TABLE[i].name;
    return "pattern";
}
void *eu_player_get(void);
void *dt_player_get(void);
void *ora_player_get(void);
void *pl_player_get(void);
void *seq_player_get(void)                       /* create_player case 3 (hook): dots, oracle, peal, euclid or finger */
{
    if (dt_active[CUR_MODE()]) return dt_player_get();
    if (ora_active[CUR_MODE()]) return ora_player_get();
    if (pl_active[CUR_MODE()]) return pl_player_get();
    return eu_player_get();
}
